import java.util.*;

class Solution {
    public boolean canGiveChange(int[] notes) {
        int fives = 0, tens = 0;
        for (int note : notes) {
            if (note == 5) {
                fives++;
            } else if (note == 10) {
                if (fives == 0) return false;
                fives--; tens++;
            } else {                              // 20: need 15 back
                if (tens > 0 && fives > 0) { tens--; fives--; }   // keep 5s when possible
                else if (fives >= 3) fives -= 3;
                else return false;
            }
        }
        return true;
    }
}

